#include "GeometryBridge.h"

#include "Kernel.h"
#include "model_core/src/ffi.rs.h"  // generated by cxx-build

namespace model {

namespace {

std::unique_ptr<Shape> wrap(TopoDS_Shape s) {
  if (s.IsNull()) return nullptr;
  return std::make_unique<Shape>(Shape{std::move(s)});
}

}  // namespace

bool shape_is_null(const Shape& shape) { return shape.value.IsNull(); }

std::unique_ptr<Shape> geom_extrude(const Profile& p, double distance) {
  switch (p.kind) {
    case ProfileKind::Rect:
      return wrap(geom::extrude(geom::RectProfile{p.width, p.height, p.x, p.y}, distance));
    case ProfileKind::Circle:
      return wrap(geom::extrude(geom::CircleProfile{p.radius, p.x, p.y}, distance));
  }
  return nullptr;
}

std::unique_ptr<Shape> geom_fuse(const Shape& a, const Shape& b) {
  return wrap(geom::fuse(a.value, b.value));
}

std::unique_ptr<Shape> geom_cut(const Shape& a, const Shape& b) {
  return wrap(geom::cut(a.value, b.value));
}

std::unique_ptr<Shape> geom_fillet_all_edges(const Shape& shape, double radius) {
  return wrap(geom::filletAllEdges(shape.value, radius));
}

}  // namespace model
